//! Evaluation-based Reed-Solomon codes over GF(256).
//!
//! The implementation uses distinct nonzero evaluation points
//! generated by powers of the primitive field element 0x02.

use crate::{GF256, polynomial::Polynomial};
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReedSolomon {
    n: usize,
    k: usize,
    evaluation_points: Vec<GF256>,
}

impl ReedSolomon {
    /// Construct an [n, k] Reed-Solomon evaluation code.
    ///
    /// Valid parameters satisfy 1 <= k <= n <= 255.
    pub fn new(n: usize, k: usize) -> Result<Self, &'static str> {
        if k == 0 || n == 0 || k > n || n > 255 {
            return Err("require 1 <= k <= n <= 255");
        }

        let alpha = GF256(0x02);
        let mut point = GF256::ONE;
        let mut evaluation_points = Vec::with_capacity(n);

        for _ in 0..n {
            evaluation_points.push(point);
            point = point.mul(alpha);
        }

        Ok(Self {
            n,
            k,
            evaluation_points,
        })
    }

    pub fn length(&self) -> usize {
        self.n
    }

    pub fn dimension(&self) -> usize {
        self.k
    }

    pub fn minimum_distance(&self) -> usize {
        self.n - self.k + 1
    }

    pub fn unique_decoding_radius(&self) -> usize {
        (self.minimum_distance() - 1) / 2
    }

    pub fn evaluation_points(&self) -> &[GF256] {
        &self.evaluation_points
    }

    /// Encode a message polynomial with exactly k coefficients.
    ///
    /// Leading zero coefficients are permitted.
    pub fn encode(&self, message: &[GF256]) -> Result<Vec<GF256>, &'static str> {
        if message.len() != self.k {
            return Err("message length must equal code dimension");
        }

        let polynomial = Polynomial::new(message.to_vec());

        Ok(self
            .evaluation_points
            .iter()
            .map(|&point| polynomial.evaluate(point))
            .collect())
    }

    /// Verify whether a word belongs to this evaluation code.
    ///
    /// This performs interpolation using the first k evaluation
    /// points and checks agreement across all n positions.
    pub fn is_codeword(&self, word: &[GF256]) -> Result<bool, &'static str> {
        if word.len() != self.n {
            return Err("word length must equal code length");
        }

        let mut coefficients = vec![GF256::ZERO; self.k];

        for (i, &xi) in self.evaluation_points.iter().take(self.k).enumerate() {
            let mut basis = Polynomial::one();
            let mut denominator = GF256::ONE;

            for j in 0..self.k {
                if i == j {
                    continue;
                }

                let xj = self.evaluation_points[j];

                basis = basis.mul(&Polynomial::new(vec![xj, GF256::ONE]));
                denominator = denominator.mul(xi.add(xj));
            }

            let weight = word[i]
                .checked_div(denominator)
                .ok_or("duplicate evaluation points")?;

            let scaled = basis.scale(weight);

            for (degree, &coefficient) in scaled.coefficients().iter().enumerate() {
                coefficients[degree] = coefficients[degree].add(coefficient);
            }
        }

        let polynomial = Polynomial::new(coefficients);

        Ok(self
            .evaluation_points
            .iter()
            .zip(word.iter())
            .all(|(&point, &value)| polynomial.evaluate(point) == value))
    }
}
